/**
 * Braille fidelity guard for AI-generated teaching material.
 *
 * Scans text for claims that tie a named sign to dot numbers, in either order:
 *   "the letter B is dots N, N"        "B: dots N N"        "the capital indicator is dot N"
 *   "\"and\" is dots N N N N N"        "the period (dots N N N)"
 *   "dots N, N is the letter B"
 * and checks each claim against the canonical UEB data in lib/braille. A wrong claim is rewritten
 * with the canonical dots (generated by lib/braille/prose.ts); a correct one is left untouched.
 *
 * Safety rules (a guard must never make correct text wrong):
 *   - A label is only checked when it unambiguously names a sign: a quoted print string, an
 *     uppercase single letter, "letter x", "digit 3" / "number 42", or a known sign name such as
 *     "numeric indicator" or "question mark". Bare words ("this", "his") are never labels, so the
 *     tail of a word is never mistaken for a letter.
 *   - Every label resolves to the full list of cell sequences that are correct for it (a letter
 *     alone or with the capital indicator; a contraction or its uncontracted spelling; a digit with
 *     or without the numeric indicator; both quotation marks for "quotation mark"). A claim that
 *     matches any of them is accepted.
 *   - A wrong claim is corrected only when exactly one correct sequence fits it (same number of
 *     cells, or the label has only one correct sequence). Otherwise it is left alone.
 * No dot pattern is typed in this file: everything comes from lib/braille.
 */

import {
  type Cell,
  type Sign,
  CONTRACTIONS,
  DIGIT_CELLS,
  INDICATORS,
  LETTER_CELLS,
  PUNCTUATION,
  SYMBOLS,
  cellsKey,
  toCell,
} from '@/lib/braille/ueb';
import { SUPERSEDED_SIGN_NAMES } from '@/lib/braille/terminology';
import { describeCells } from '@/lib/braille/prose';
import { transcribe } from '@/lib/braille/transcribe';

export interface CorrectionEntry {
  /** The dot description as the text had it. */
  original: string;
  /** The canonical dot description it was replaced with. */
  corrected: string;
  /** Surrounding text snippet. */
  context: string;
  /** What the claim was about, e.g. "B", "and", "numeric indicator". */
  letterOrContraction: string;
}

export type Seq = readonly Cell[];

export interface Target {
  label: string;
  /** Every cell sequence that is a correct way to write this label. */
  accepted: Seq[];
}

/* ── Label tables (built from lib/braille) ───────────────────────────────── */

const CAP = INDICATORS.capitalLetter.cells[0];
const NUM = INDICATORS.numeric.cells[0];

/** Extra names people (and models) use for the same signs. Names only, never dots. */
const NAME_ALIASES: Readonly<Record<string, readonly string[]>> = {
  capitalLetter: ['capital indicator', 'capital sign', 'capitals indicator', 'capital symbol indicator'],
  capitalWord: [
    'capital word indicator',
    'capitalised word indicator',
    ...SUPERSEDED_SIGN_NAMES.capitalWord,
    'all-caps indicator',
    'all caps indicator',
  ],
  capitalPassage: ['capitalised passage indicator', 'capital passage indicator'],
  capitalsTerminator: ['capital terminator', 'capitalisation terminator', 'capitalization terminator'],
  numeric: [...SUPERSEDED_SIGN_NAMES.numeric, 'numeric sign', 'numeric prefix'],
  grade1Symbol: [
    'grade 1 symbol indicator',
    'grade one indicator',
    'grade one symbol indicator',
    ...SUPERSEDED_SIGN_NAMES.grade1Symbol,
  ],
  grade1Word: ['grade one word indicator'],
  period: ['full stop'],
  exclamation: ['exclamation point'],
  openQuote: ['opening double quotation mark', 'open quotation mark', 'opening quote', 'open quote'],
  closeQuote: ['closing double quotation mark', 'close quotation mark', 'closing quote', 'close quote'],
  openParen: ['open parenthesis', 'left parenthesis'],
  closeParen: ['close parenthesis', 'right parenthesis'],
  slash: ['forward slash'],
  at: ['at symbol'],
  percent: ['percent symbol'],
  times: ['times sign'],
  equals: ['equal sign'],
};

/** Names that cover more than one sign: a claim about them is accepted if it fits any. */
const GROUP_NAMES: Readonly<Record<string, readonly string[]>> = {
  'quotation mark': ['openQuote', 'closeQuote'],
  'double quotation mark': ['openQuote', 'closeQuote'],
  'single quotation mark': ['openSingleQuote', 'closeSingleQuote'],
  parenthesis: ['openParen', 'closeParen'],
};

const NAMED_SIGNS: readonly Sign[] = [
  ...Object.values(INDICATORS),
  ...Object.values(PUNCTUATION),
  ...Object.values(SYMBOLS),
];

function addAccepted(map: Map<string, Target>, key: string, label: string, seqs: Seq[]) {
  const existing = map.get(key);
  const target = existing ?? { label, accepted: [] };
  for (const s of seqs) if (!target.accepted.some((a) => cellsKey(a) === cellsKey(s))) target.accepted.push(s);
  map.set(key, target);
}

function buildNameTable(): Map<string, Target> {
  const map = new Map<string, Target>();
  for (const sign of NAMED_SIGNS) {
    const names = [sign.name, ...(NAME_ALIASES[sign.id] ?? [])];
    for (const n of names) addAccepted(map, n.toLowerCase(), sign.name, [sign.cells]);
  }
  for (const [n, ids] of Object.entries(GROUP_NAMES)) {
    const signs = NAMED_SIGNS.filter((s) => ids.includes(s.id));
    addAccepted(
      map,
      n,
      n,
      signs.map((s) => s.cells),
    );
  }
  return map;
}

const NAME_TABLE = buildNameTable();

function safeTranscribe(print: string): Cell[] | null {
  try {
    return transcribe(print);
  } catch {
    return null;
  }
}

function letterTarget(letter: string): Target | null {
  const l = letter.toLowerCase();
  const cell = LETTER_CELLS[l];
  if (!cell) return null;
  return { label: letter.toUpperCase(), accepted: [[cell], [CAP, cell]] };
}

function numberTarget(digits: string): Target | null {
  if (!/^[0-9]+$/.test(digits)) return null;
  const full = safeTranscribe(digits);
  if (!full) return null;
  const accepted: Seq[] = [full];
  // Teaching material often gives a digit's own cell ("3 uses the cell of c") without the indicator.
  if (cellsKey(full.slice(0, 1)) === cellsKey([NUM])) accepted.push(full.slice(1));
  if (digits.length === 1) accepted.push([DIGIT_CELLS[digits]]);
  return { label: digits, accepted };
}

/** A quoted print string: a letter, a number, a punctuation mark or symbol, or a contraction. */
function quotedTarget(raw: string): Target | null {
  const text = raw.trim();
  if (!text) return null;
  if (/^[A-Za-z]$/.test(text)) return letterTarget(text);
  if (/^[0-9]+$/.test(text)) return numberTarget(text);
  const lower = text.toLowerCase();
  const contractions = CONTRACTIONS.filter((c) => c.text === lower);
  if (contractions.length > 0) {
    const accepted: Seq[] = contractions.map((c) => c.cells);
    const spelled = safeTranscribe(lower);
    if (spelled) accepted.push(spelled);
    return { label: lower, accepted: dedupe(accepted) };
  }
  const bySign = NAMED_SIGNS.filter((s) => s.print === text);
  if (bySign.length > 0) return { label: text, accepted: dedupe(bySign.map((s) => s.cells)) };
  const named = NAME_TABLE.get(lower);
  if (named) return named;
  return null; // an arbitrary quoted word: not checked (it could be meant contracted or not)
}

function dedupe(seqs: Seq[]): Seq[] {
  const seen = new Set<string>();
  return seqs.filter((s) => {
    const k = cellsKey(s);
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

/* ── Claim grammar ────────────────────────────────────────────────────────── */

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const NAMES_ALT = [...NAME_TABLE.keys()]
  .sort((a, b) => b.length - a.length)
  .map((n) => escapeRe(n).replace(/ /g, '\\s+'))
  .join('|');

/** Horizontal whitespace: a claim never runs across a line break. */
const S = '[^\\S\\n]';
/** One dot number; refuses to swallow a following count ("and 3 other letters"). */
const DOT_NUM = `[1-6](?![0-9])(?!${S}+(?:other|more|of|letters?|cells?|times|words?|dots|signs?)\\b)`;
const DOT_NUMS = `${DOT_NUM}(?:(?:${S}*,${S}*|${S}+and${S}+|${S}*[-–]${S}*|${S}+)${DOT_NUM})*`;
const CELL_SEP = `(?:${S}*,?${S}*(?:and${S}+then|then|followed${S}+by|\\+)${S}+(?:dots?${S}+)?|${S}*,${S}*dots?${S}+|${S}+dots?${S}+)`;
const DOT_SPEC = `dots?${S}+${DOT_NUMS}(?:${CELL_SEP}${DOT_NUMS})*`;

const LABEL = [
  `["“‘'](?<q>[^"'“”‘’\\n]{1,30})["”’']`,
  `\\b(?:the${S}+)?letter${S}+(?<letter>[a-z])\\b(?!['’])`,
  `\\b(?<upper>[a-z])\\b(?!['’])`,
  `\\b(?:the${S}+)?(?:digit|number|numeral)${S}+(?<num>[0-9]+)\\b`,
  `\\b(?:the${S}+)?(?<name>${NAMES_ALT})\\b`,
].join('|');

const KIND_WORD = `(?:${S}+(?:contraction|wordsign|groupsign|sign|indicator|symbol|cell|character))?`;
const FORWARD_CONNECTOR = `${S}*(?:\\(${S}*|[:=—–]${S}*|${S}-${S}+|\\b(?:is|are|uses|has)${S}+(?:written${S}+(?:as|with)${S}+|formed${S}+(?:by|from|with)${S}+|made${S}+(?:up${S}+)?(?:of|from|with)${S}+)?)(?:the${S}+)?(?:raised${S}+)?`;
const REVERSE_CONNECTOR = `${S}*\\)?${S}*(?:is|are|=|means|represents|stands${S}+for|makes|forms|gives|→|->)${S}+(?:the${S}+)?`;

const FORWARD_RE = new RegExp(`(?:${LABEL})${KIND_WORD}${FORWARD_CONNECTOR}(?<spec>${DOT_SPEC})`, 'gi');
const REVERSE_RE = new RegExp(`(?<spec>${DOT_SPEC})${REVERSE_CONNECTOR}(?:${LABEL})`, 'gi');

/** Any dot-number phrase ("dots N, N", "dot N then dots N N"), labelled or not. */
export function dotSpecRegExp(): RegExp {
  return new RegExp(DOT_SPEC, 'gi');
}

/** Split a matched dot description into cells, e.g. "dot N, then dots N, N" → two cells. */
export function parseDotSpec(spec: string): Cell[] {
  const parts = spec.split(/\s*,?\s*(?:and\s+then|then|followed\s+by|\+)\s+|(?=\bdots?\b)/i);
  const cells: Cell[] = [];
  for (const part of parts) {
    const nums = (part.match(/[1-6]/g) ?? []).map(Number);
    if (nums.length > 0) cells.push(toCell(nums));
  }
  return cells;
}

function resolveLabel(groups: Record<string, string | undefined>): Target | null {
  if (groups.q !== undefined) return quotedTarget(groups.q);
  if (groups.letter !== undefined) return letterTarget(groups.letter);
  if (groups.upper !== undefined) {
    // An unquoted single letter counts only when written as a capital ("B is ..."), so the article
    // "a" or a stray lowercase letter is never treated as a claim.
    return groups.upper === groups.upper.toUpperCase() ? letterTarget(groups.upper) : null;
  }
  if (groups.num !== undefined) return numberTarget(groups.num);
  if (groups.name !== undefined) return NAME_TABLE.get(groups.name.toLowerCase().replace(/\s+/g, ' ')) ?? null;
  return null;
}

/** What to do with a claim: 'ok', a corrected sequence, or null (leave alone: not decidable). */
export function judgeClaim(accepted: readonly Seq[], claimed: Seq): 'ok' | Seq | null {
  if (claimed.length === 0) return null;
  const key = cellsKey(claimed);
  if (accepted.some((a) => cellsKey(a) === key)) return 'ok';
  const distinct = dedupe([...accepted]);
  if (distinct.length === 1) return distinct[0];
  const sameLength = distinct.filter((a) => a.length === claimed.length);
  return sameLength.length === 1 ? sameLength[0] : null;
}

export interface Claim {
  specStart: number;
  specEnd: number;
  spec: string;
  target: Target;
}

export function findClaims(text: string): Claim[] {
  const claims: Claim[] = [];
  const overlaps = (s: number, e: number) => claims.some((c) => s < c.specEnd && e > c.specStart);
  for (const re of [FORWARD_RE, REVERSE_RE]) {
    re.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text)) !== null) {
      const groups = m.groups ?? {};
      const spec = groups.spec!;
      // Index of the spec inside the match: forward claims end with it, reverse claims start with it.
      const specStart = re === FORWARD_RE ? m.index + m[0].length - spec.length : m.index;
      const specEnd = specStart + spec.length;
      const target = resolveLabel(groups);
      // "1 is dot N, 2 is ...": a forward claim whose dots run straight into another "is" may have
      // swallowed the next label, so it is not decidable. Leave it alone.
      const runsOn = re === FORWARD_RE && /^\s*(?:is|are|=|means|represents)\b/i.test(text.slice(specEnd));
      if (target && !runsOn && !overlaps(specStart, specEnd)) claims.push({ specStart, specEnd, spec, target });
      if (m[0].length === 0) re.lastIndex++;
    }
  }
  return claims.sort((a, b) => a.specStart - b.specStart);
}

/** Validate and correct braille dot claims in one string. */
export function validateBrailleText(text: string): {
  correctedText: string;
  corrections: CorrectionEntry[];
} {
  const corrections: CorrectionEntry[] = [];
  let correctedText = text;
  const claims = findClaims(text);
  // Replace from the end so earlier offsets stay valid.
  for (let i = claims.length - 1; i >= 0; i--) {
    const c = claims[i];
    const verdict = judgeClaim(c.target.accepted, parseDotSpec(c.spec));
    if (verdict === 'ok' || verdict === null) continue;
    const replacement = describeCells(verdict);
    corrections.unshift({
      original: c.spec,
      corrected: replacement,
      context: text.slice(Math.max(0, c.specStart - 30), Math.min(text.length, c.specEnd + 20)),
      letterOrContraction: c.target.label,
    });
    correctedText = correctedText.slice(0, c.specStart) + replacement + correctedText.slice(c.specEnd);
  }
  return { correctedText, corrections };
}

/**
 * Validates and corrects braille content in a parsed JSON structure.
 * Recursively walks through all string values in the JSON.
 */
export function validateContentJson(parsed: unknown): {
  corrected: unknown;
  corrections: CorrectionEntry[];
  wasCorrected: boolean;
} {
  const allCorrections: CorrectionEntry[] = [];

  function walk(obj: unknown): unknown {
    if (typeof obj === 'string') {
      const { correctedText, corrections } = validateBrailleText(obj);
      allCorrections.push(...corrections);
      return correctedText;
    }
    if (Array.isArray(obj)) return obj.map(walk);
    if (obj !== null && typeof obj === 'object') {
      const result: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(obj as Record<string, unknown>)) result[key] = walk(value);
      return result;
    }
    return obj;
  }

  const corrected = walk(parsed);
  return { corrected, corrections: allCorrections, wasCorrected: allCorrections.length > 0 };
}
